add_cart_item.code:
const response = await client.carts.addCartItem({
    product_id: 101,
    quantity: 1,
    customer_id: 45,
    session_id: 'cart-7f3a9c2e1b',
    shipping_address: {
        first_name: 'Alex', last_name: 'Taylor', address_line1: '1 Example Street', address_line2: '',
        city: 'Sydney', post_code: '2000', phone: '', mobile: '', fax: '', email: 'alex.taylor@example.com',
        country_code: 'AU', state_code: 'NSW',
    },
});
console.log(response.map.cart.session_id, response.map.cart.items[0].id, response.map.cart.shipping.shipping_tax);

get_cart.code:
const response = await client.carts.getCart('cart-7f3a9c2e1b');
const cart = response.map.cart;
for (const item of cart.items) {
    console.log(item.id, item.product.name, item.quantity, item.pricing.total);
}
console.log(cart.totals.subtotal, cart.shipping.shipping_tax, cart.totals.grand_total);

update_cart_item.code:
const response = await client.carts.updateCartItem('cart-7f3a9c2e1b', {cart_item_id: 42, quantity: 2});
const cart = response.map.cart;
for (const item of cart.items) {
    console.log(item.id, item.quantity, item.pricing.total);
}
console.log(cart.totals.subtotal, cart.totals.grand_total);

create_order_from_cart.code:
const response = await client.carts.createOrderFromCart('cart-7f3a9c2e1b', {
    customer_id: 123,
    payment_gateway: 'PIS',
    delivery_type: 'shipping',
    transaction_no: 'web-order-0001',
});
const order = response.map.order;
console.log(response.map.status, order.order_id, order.order_status, order.payment_status, order.grand_total);
